formula.expression:
lets(
  /* Get job title and location information, normalized to lowercase */
  jobTitle, if(empty({{notion:block_property:title:00000000-0000-0000-0000-000000000000:7e0def65-baa5-81f6-bec7-00036d03ac77}}), "", {{notion:block_property:title:00000000-0000-0000-0000-000000000000:7e0def65-baa5-81f6-bec7-00036d03ac77}}).lower(),
  location, (if(empty({{notion:block_property:IuLZ:00000000-0000-0000-0000-000000000000:7e0def65-baa5-81f6-bec7-00036d03ac77}}), "", {{notion:block_property:IuLZ:00000000-0000-0000-0000-000000000000:7e0def65-baa5-81f6-bec7-00036d03ac77}}) + ", " + 
            if(empty({{notion:block_property:nVFR:00000000-0000-0000-0000-000000000000:7e0def65-baa5-81f6-bec7-00036d03ac77}}), "", {{notion:block_property:nVFR:00000000-0000-0000-0000-000000000000:7e0def65-baa5-81f6-bec7-00036d03ac77}})).lower(),

  /* Primary program detection based on keywords in job title */
  ifs(
    /* Aegis detection */
    jobTitle.contains("aegis"), "Aegis",

    /* MFC detection */
    jobTitle.contains("mfc") or jobTitle.contains("fire control") or (jobTitle.contains("fire") and jobTitle.contains("control")), "MFC",

    /* PAC-3 MSE detection */
    jobTitle.contains("pac-3") or jobTitle.contains("pac3") or 
    jobTitle.contains("patriot") or jobTitle.contains("mse"), "PAC-3 MSE",

    /* THAAD detection */
    jobTitle.contains("thaad") or jobTitle.contains("terminal high altitude") or 
    (location.contains("troy") and location.contains("al")), "THAAD",

    /* PrSM detection */
    jobTitle.contains("prsm") or jobTitle.contains("precision strike"), "PrSM",

    /* GMLRS detection */
    jobTitle.contains("gmlrs") or jobTitle.contains("mlrs") or 
    jobTitle.contains("guided multiple"), "GMLRS",

    /* JASSM detection */
    jobTitle.contains("jassm"), "JASSM",

    /* LRASM detection */
    jobTitle.contains("lrasm"), "LRASM",

    /* Javelin detection */
    jobTitle.contains("javelin"), "Javelin",

    /* GWS detection */
    jobTitle.contains("gws") or jobTitle.contains("guam weapon") or 
    jobTitle.contains("aegis ashore"), "Aegis / GWS",

    /* SM-6 detection */
    jobTitle.contains("sm-6") or jobTitle.contains("sm6"), "SM-6 Integration",

    /* NGI detection */
    jobTitle.contains("ngi") or jobTitle.contains("next generation interceptor"), "NGI",

    /* FBM detection */
    jobTitle.contains("fbm") or jobTitle.contains("fleet ballistic") or 
    jobTitle.contains("trident"), "FBM",

    /* NGG-OPIR detection */
    jobTitle.contains("opir") or jobTitle.contains("ngg") or 
    jobTitle.contains("overhead persistent"), "NGG-OPIR",

    /* LRHW / CPS detection */
    jobTitle.contains("lrhw") or jobTitle.contains("hypersonic") or 
    jobTitle.contains("cps") or jobTitle.contains("arrw"), "LRHW / CPS",

    /* Aegis / GWS additional detection */
    jobTitle.contains("naval systems") or jobTitle.contains("combat systems") or 
    jobTitle.contains("shipboard") or jobTitle.contains("aegis weapon"), "Aegis / GWS",

    /* JASSM / LRASM additional detection */
    jobTitle.contains("strike weapons") or jobTitle.contains("long range strike") or 
    jobTitle.contains("cruise missile"), "JASSM / LRASM",

    /* NGI additional detection */
    jobTitle.contains("missile defense agency") or jobTitle.contains("interceptor") or 
    jobTitle.contains("kill vehicle"), "NGI",

    /* NGG-OPIR additional detection */
    jobTitle.contains("satellite") or jobTitle.contains("space systems") or 
    jobTitle.contains("orbital"), "NGG-OPIR",

    /* Location-based fallback */
    location.contains("camden"), "PAC-3 MSE",
    location.contains("grand prairie") or location.contains("dallas"), "PAC-3 MSE / Precision Fires",
    location.contains("orlando") or location.contains("ocala"), "JASSM / LRASM",
    location.contains("troy") or (location.contains("al") and jobTitle.contains("quality")), "JASSM / Javelin",
    location.contains("moorestown") or location.contains("huntsville"), "Aegis / GWS / SM-6",
    location.contains("sunnyvale") or location.contains("littleton") or location.contains("denver"), "NGI / FBM / NGG-OPIR",

    /* Default if no match found */
    "Unclassified Program"
  )
)
